// tentacule et lève l'ambiguïté de silhouette qu'avait le tube lisse.
// Le relief vient des ventouses ombrées, pas d'une arête lumineuse — une
// bande claire décalée délave le bras au lieu de l'arrondir.

/** Un palier de trait : largeur, et portion du tracé qu'il couvre. */
export interface ArmSegment {
  width: number;
  dash: string;
}

/** Une ventouse : centre et rayon, dans le repère 240×240. */
export interface Sucker {
  cx: number;
  cy: number;
  r: number;
}

